package core.replay;
import com.aoo.bcg.common.persistence.DriverManagerDataSource;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="AOO_DB_IT_URL",matches=".+")class ReplayArchiveIntegrationTest{
 @Test void archivePreservesAuthorizationPerspectiveOrderingAndVersion()throws Exception{var ds=new DriverManagerDataSource(System.getenv("AOO_DB_IT_URL"),System.getenv("AOO_DB_IT_USER"),System.getenv("AOO_DB_IT_PASSWORD"));long room=System.currentTimeMillis();int set=3;long player=room+1,other=room+2;var participants=new JdbcReplayParticipantRegistry(ds);participants.grant(room,set,player,2);participants.grant(room,set,other,1);var repo=new JdbcPerspectiveReplayRepository(ds);repo.append(new PerspectiveReplayEvent(room,set,1,ReplayEventVisibility.PUBLIC,0,"public",new byte[]{1},2,"pdk-v2"));repo.append(new PerspectiveReplayEvent(room,set,2,ReplayEventVisibility.PLAYER_PRIVATE,player,"mine",new byte[]{2},2,"pdk-v2"));repo.append(new PerspectiveReplayEvent(room,set,2,ReplayEventVisibility.PLAYER_PRIVATE,other,"other",new byte[]{9},2,"pdk-v2"));try(var c=ds.getConnection();var q=c.prepareStatement("UPDATE perspective_replay_event SET created_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 2 DAY) WHERE room_id=?")){q.setLong(1,room);q.executeUpdate();}var retention=new JdbcReplayRetentionService(ds);assertEquals(3,retention.archiveExpiredEvents(Instant.now().minus(Duration.ofDays(1)),100));assertEquals(2,retention.deleteOrphanParticipants(Instant.now().plus(Duration.ofDays(1)),100));var view=new PerspectiveReplayService(repo,participants).loadPlayerView(room,set,player);assertEquals(List.of("public","mine"),view.stream().map(PerspectiveReplayEvent::getMessageId).toList());assertTrue(view.stream().allMatch(e->e.getSchemaVersion()==2&&e.getPlayVersion().equals("pdk-v2")));assertTrue(participants.mayView(room,set,player,2));assertFalse(participants.mayView(room,set,player,1));try(var c=ds.getConnection();var q=c.prepareStatement("DELETE FROM perspective_replay_event_archive WHERE room_id=?")){q.setLong(1,room);q.executeUpdate();}try(var c=ds.getConnection();var q=c.prepareStatement("DELETE FROM replay_participant_archive WHERE room_id=?")){q.setLong(1,room);q.executeUpdate();}}
}
